    {
        double rate = 0.0;
        // TODO (R1, R2): one chain of decisions, two questions at most.
        if(weightKg >= MEDIUM_LIMIT)
            rate = HEAVY_RATE;
        if(weightKg >= LIGHT_LIMIT)
            rate = MEDIUM_RATE;
        if(weightKg < LIGHT_LIMIT)
            rate = LIGHT_RATE;
        return rate;
    }

    public static boolean isOutOfRange(double weightKg)
    {
        // TODO (R3): which weights can never make this true?
        return weightKg < MIN_WEIGHT && weightKg > MAX_WEIGHT;
